-- public.errors_wrong_artist_usa_uk_origin source

CREATE OR REPLACE VIEW public.errors_wrong_artist_usa_uk_origin
AS SELECT id,
    artist_name,
    origin
   FROM artists
  WHERE (origin::text ~~ '%US%'::text OR origin::text ~~ '%United State%'::text OR origin::text ~~ '%U.S.%'::text) AND (origin::text !~~ ALL (ARRAY['%, Alabama, USA'::character varying::text, '%, Alaska, USA'::character varying::text, '%, Arizona, USA'::character varying::text, '%, Arkansas, USA'::character varying::text, '%, California, USA'::character varying::text, '%, Colorado, USA'::character varying::text, '%, Connecticut, USA'::character varying::text, '%, D.C., USA'::character varying::text, '%, Delaware, USA'::character varying::text, '%, Florida, USA'::character varying::text, '%, Georgia, USA'::character varying::text, '%, Hawaii, USA'::character varying::text, '%, Idaho, USA'::character varying::text, '%, Illinois, USA'::character varying::text, '%, Indiana, USA'::character varying::text, '%, Iowa, USA'::character varying::text, '%, Kansas, USA'::character varying::text, '%, Kentucky, USA'::character varying::text, '%, Louisiana, USA'::character varying::text, '%, Maine, USA'::character varying::text, '%, Maryland, USA'::character varying::text, '%, Massachusetts, USA'::character varying::text, '%, Michigan, USA'::character varying::text, '%, Minnesota, USA'::character varying::text, '%, Mississippi, USA'::character varying::text, '%, Missouri, USA'::character varying::text, '%, Montana, USA'::character varying::text, '%, Nebraska, USA'::character varying::text, '%, Nevada, USA'::character varying::text, '%, New Hampshire, USA'::character varying::text, '%, New Jersey, USA'::character varying::text, '%, New Mexico, USA'::character varying::text, '%, New York, USA'::character varying::text, '%, North Carolina, USA'::character varying::text, '%, North Dakota, USA'::character varying::text, '%, Ohio, USA'::character varying::text, '%, Oklahoma, USA'::character varying::text, '%, Oregon, USA'::character varying::text, '%, Pennsylvania, USA'::character varying::text, '%, Rhode Island, USA'::character varying::text, '%, South Carolina, USA'::character varying::text, '%, South Dakota, USA'::character varying::text, '%, Tennessee, USA'::character varying::text, '%, Texas, USA'::character varying::text, '%, Utah, USA'::character varying::text, '%, Vermont, USA'::character varying::text, '%, Virginia, USA'::character varying::text, '%, Washington, USA'::character varying::text, '%, West Virginia, USA'::character varying::text, '%, Wisconsin, USA'::character varying::text, '%, Wyoming, USA'::character varying::text])) OR (origin::text ~~ '%UK%'::text OR origin::text ~~ '%U.K.%'::text OR origin::text ~~ '%United Kingdom%'::text OR origin::text ~~ '%England%'::text OR origin::text ~~ '%Scotland%'::text OR origin::text ~~ '%Wales%'::text OR origin::text ~~ '%Northern Ireland%'::text) AND origin::text !~~ '%, England, UK'::text AND origin::text !~~ '%, Scotland, UK'::text AND origin::text !~~ '%, Wales, UK'::text AND origin::text !~~ '%, Northern Ireland, UK'::text
  ORDER BY artist_name;